"""Dependency-free mobile-first web workspace for Amodex."""

WORKSPACE_HTML = r'''<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>Amodex Workspace</title>
<style>
:root{color-scheme:dark;--bg:#0b0d10;--panel:#11151a;--panel2:#171c22;--line:#28313b;--text:#eef2f6;--muted:#8793a0;--accent:#80bfff;--good:#58d68d;--warn:#f0b35b;--bad:#ff6b6b;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);height:100dvh;overflow:hidden}button,input,textarea,select{font:inherit;color:inherit;background:#0d1116;border:1px solid var(--line);border-radius:10px}button{cursor:pointer;padding:9px 12px}button:hover{border-color:var(--accent)}input,textarea,select{padding:10px;width:100%}textarea{resize:none}.app{height:100dvh;display:grid;grid-template-columns:290px minmax(0,1fr) 320px}.side,.context{background:var(--panel);overflow:auto}.side{border-right:1px solid var(--line);padding:14px}.context{border-left:1px solid var(--line);padding:14px}.brand{font-weight:800;font-size:1.15rem;display:flex;justify-content:space-between;align-items:center}.badge{font-size:.72rem;border:1px solid var(--line);border-radius:999px;padding:4px 7px;color:var(--muted)}.section{margin-top:18px}.section h3{font-size:.78rem;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin:0 0 8px}.stack{display:flex;flex-direction:column;gap:6px}.item{padding:10px;border:1px solid transparent;border-radius:10px;background:transparent;text-align:left;width:100%}.item:hover,.item.active{background:var(--panel2);border-color:var(--line)}.item small{display:block;color:var(--muted);margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.main{min-width:0;display:flex;flex-direction:column;height:100dvh}.topbar{height:58px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:10px 16px;background:rgba(11,13,16,.94);backdrop-filter:blur(8px)}.topbar .title{font-weight:700}.chat{flex:1;overflow:auto;padding:24px max(18px,calc((100% - 820px)/2));scroll-behavior:smooth}.empty{max-width:620px;margin:18vh auto 0;text-align:center;color:var(--muted)}.empty h1{color:var(--text);font-size:1.8rem}.message{max-width:760px;margin:0 auto 18px}.message .who{font-size:.72rem;color:var(--muted);margin-bottom:5px}.bubble{white-space:pre-wrap;line-height:1.48;border-radius:14px;padding:12px 14px;background:var(--panel2);border:1px solid var(--line)}.message.owner .bubble{background:#142031}.composer-wrap{border-top:1px solid var(--line);padding:12px max(14px,calc((100% - 860px)/2));background:var(--bg)}.composer{border:1px solid var(--line);border-radius:16px;background:var(--panel);padding:9px}.composer textarea{border:0;background:transparent;min-height:58px;max-height:180px;outline:none}.composer-actions{display:flex;gap:7px;align-items:center;justify-content:space-between}.left-actions,.right-actions{display:flex;gap:7px;align-items:center}.primary{background:#e8f2ff;color:#10151b;border-color:#e8f2ff;font-weight:700}.subtle{color:var(--muted)}.warning{margin:8px 0 0;color:var(--warn);font-size:.75rem}.context-card{border:1px solid var(--line);border-radius:12px;padding:11px;margin-bottom:10px;background:var(--panel2)}.context-card h4{margin:0 0 7px}.muted{color:var(--muted);font-size:.82rem}.good{color:var(--good)}.warn{color:var(--warn)}.danger{color:var(--bad)}.row{display:flex;gap:7px;align-items:center}.row>*{min-width:0}.modal{position:fixed;inset:0;background:#000a;display:none;place-items:center;padding:18px;z-index:20}.modal.open{display:grid}.dialog{width:min(520px,100%);max-height:85dvh;overflow:auto;background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:16px}.dialog h2{margin-top:0}.dialog label{display:block;color:var(--muted);font-size:.8rem;margin:10px 0 4px}.dialog .actions{display:flex;justify-content:flex-end;gap:7px;margin-top:14px}.mobile-menu,.mobile-context{display:none}.error{position:fixed;right:14px;bottom:14px;max-width:420px;padding:12px;border-radius:12px;background:#3a1717;border:1px solid var(--bad);display:none;z-index:40}.draft{border-left:3px solid var(--accent)}.memory{border-left:3px solid var(--warn)}@media(max-width:1000px){.app{grid-template-columns:260px minmax(0,1fr)}.context{position:fixed;right:0;top:0;bottom:0;width:min(340px,90vw);z-index:15;transform:translateX(100%);transition:.2s}.context.open{transform:none}.mobile-context{display:inline-flex}}@media(max-width:700px){.app{display:block}.side{position:fixed;left:0;top:0;bottom:0;width:min(300px,88vw);z-index:16;transform:translateX(-100%);transition:.2s}.side.open{transform:none}.mobile-menu{display:inline-flex}.chat{padding:18px 12px}.topbar{padding:9px 10px}.composer-wrap{padding:8px}.hide-mobile{display:none}}
</style>
</head>
<body>
<div class="app">
<aside id="side" class="side"><div class="brand"><span>Amodex</span><span id="statusBadge" class="badge">workspace</span></div><button class="item" onclick="openWorkspaceModal()">＋ Novo projeto</button><div class="section"><h3>Projetos</h3><div id="workspaceList" class="stack"></div></div><div class="section"><div class="row"><h3 style="flex:1">Chats</h3><button onclick="openChatModal()">＋</button></div><div id="chatList" class="stack"></div></div><div class="section"><h3>Ambientes</h3><div id="environmentList" class="stack"></div></div><div class="section"><h3>Sistema</h3><button class="item" onclick="location.href='/docs'">API / Docs</button></div></aside>
<main class="main"><header class="topbar"><div class="row"><button class="mobile-menu" onclick="toggleSide()">☰</button><div><div id="chatTitle" class="title">Amodex Workspace</div><div id="workspaceTitle" class="muted">Selecione um projeto</div></div></div><div class="row"><span id="inferenceBadge" class="badge warn">AI gated</span><button class="mobile-context" onclick="toggleContext()">Contexto</button></div></header><section id="messages" class="chat"><div class="empty"><h1>Seu espaço de trabalho</h1><p>Crie um projeto, abra chats e organize ideias. Conversar não executa código: só um Environment autorizado pode criar Runs.</p></div></section><footer class="composer-wrap"><div class="composer"><textarea id="composer" placeholder="Converse, planeje ou prepare uma tarefa…" disabled></textarea><div class="composer-actions"><div class="left-actions"><button class="subtle" onclick="openMemoryModal()" title="Salvar como memória candidata">Memória</button><button class="subtle" onclick="openDraftModal()" title="Transformar texto em Execution Draft">Cozinhar</button></div><div class="right-actions"><select id="activeEnvironment" class="hide-mobile" style="width:180px"><option value="">Sem ambiente</option></select><button class="primary" onclick="sendMessage()">Enviar</button></div></div><div class="warning">Inferência da Amodex continua bloqueada até benchmark/promoção dos modelos. O chat não executa tarefas sozinho.</div></div></footer></main>
<aside id="context" class="context"><div class="brand"><span>Contexto</span><button class="mobile-context" onclick="toggleContext()">✕</button></div><div class="section"><h3>Project Memory</h3><div id="memoryList"></div><button onclick="openMemoryModal()">＋ Memória candidata</button></div><div class="section"><h3>Execution Drafts</h3><div id="draftList"></div></div><div class="section"><h3>Ambientes vinculados</h3><div id="boundEnvironmentList"></div><button onclick="openBindEnvironmentModal()">Vincular ambiente</button></div><div class="section"><h3>Próximas camadas</h3><div class="context-card muted">Passo 2: GitHub/Roblox Connectors<br>Passo 3: arquivos, imagens e STT<br>Passo 4: Model Intelligence</div></div></aside>
</div>
<div id="workspaceModal" class="modal"><form class="dialog" onsubmit="createWorkspace(event)"><h2>Novo projeto</h2><label>Nome</label><input id="newWorkspaceName" required maxlength="160"><label>Descrição</label><textarea id="newWorkspaceDescription" maxlength="4000"></textarea><div class="actions"><button type="button" onclick="closeModal('workspaceModal')">Cancelar</button><button class="primary">Criar</button></div></form></div>
<div id="chatModal" class="modal"><form class="dialog" onsubmit="createChat(event)"><h2>Novo chat</h2><label>Título</label><input id="newChatTitle" required maxlength="200"><label>Ambiente ativo (opcional)</label><select id="newChatEnvironment"><option value="">Nenhum</option></select><div class="actions"><button type="button" onclick="closeModal('chatModal')">Cancelar</button><button class="primary">Criar</button></div></form></div>
<div id="memoryModal" class="modal"><form class="dialog" onsubmit="createMemory(event)"><h2>Memória candidata</h2><p class="muted">Nada vira memória canônica automaticamente. Você aprova depois.</p><label>Conteúdo</label><textarea id="memoryContent" required maxlength="100000"></textarea><label>Origem (opcional)</label><input id="memorySource" maxlength="1000" placeholder="chat: decisão de arquitetura"><div class="actions"><button type="button" onclick="closeModal('memoryModal')">Cancelar</button><button class="primary">Salvar candidata</button></div></form></div>
<div id="draftModal" class="modal"><form class="dialog" onsubmit="createDraft(event)"><h2>Execution Draft</h2><p class="muted">Draft organiza a execução, mas não inicia Run automaticamente.</p><label>Título</label><input id="draftTitle" required maxlength="200"><label>Objetivo</label><textarea id="draftObjective" required maxlength="100000"></textarea><label>Instruções</label><textarea id="draftInstructions" required maxlength="200000"></textarea><label>Validação</label><textarea id="draftValidation" maxlength="100000"></textarea><label>Environment</label><select id="draftEnvironment"><option value="">Selecionar depois</option></select><div class="actions"><button type="button" onclick="closeModal('draftModal')">Cancelar</button><button class="primary">Criar draft</button></div></form></div>
<div id="bindEnvironmentModal" class="modal"><form class="dialog" onsubmit="bindEnvironment(event)"><h2>Vincular Environment</h2><label>Environment existente</label><select id="bindEnvironmentSelect" required></select><label>Nome no projeto (opcional)</label><input id="bindEnvironmentLabel" maxlength="160"><div class="actions"><button type="button" onclick="closeModal('bindEnvironmentModal')">Cancelar</button><button class="primary">Vincular</button></div></form></div>
<div id="error" class="error"></div>
<script>
const state={workspaces:[],workspace:null,chats:[],chat:null,messages:[],memories:[],envBindings:[],allEnvironments:[],drafts:[]};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,opt={}){const r=await fetch(path,{headers:{'content-type':'application/json',...(opt.headers||{})},...opt});let body=null;try{body=await r.json()}catch{}if(!r.ok){const d=body?.detail;throw new Error(d?.message||d?.code||(typeof d==='string'?d:null)||r.statusText)}return body}
function err(e){const x=document.getElementById('error');x.textContent=e.message||e;x.style.display='block';clearTimeout(window.__err);window.__err=setTimeout(()=>x.style.display='none',5000)}
function openModal(id){document.getElementById(id).classList.add('open')}function closeModal(id){document.getElementById(id).classList.remove('open')}function toggleSide(){side.classList.toggle('open')}function toggleContext(){context.classList.toggle('open')}
function openWorkspaceModal(){openModal('workspaceModal')}function openChatModal(){if(!state.workspace)return err(new Error('Crie ou selecione um projeto primeiro'));fillEnvironmentSelects();openModal('chatModal')}function openMemoryModal(){if(!state.workspace)return err(new Error('Selecione um projeto'));if(state.chat&&composer.value.trim()&&!memoryContent.value)memoryContent.value=composer.value.trim();openModal('memoryModal')}function openDraftModal(){if(!state.chat)return err(new Error('Selecione um chat'));const text=composer.value.trim();if(text){if(!draftObjective.value)draftObjective.value=text;if(!draftInstructions.value)draftInstructions.value=text}fillEnvironmentSelects();openModal('draftModal')}function openBindEnvironmentModal(){if(!state.workspace)return err(new Error('Selecione um projeto'));fillEnvironmentSelects();openModal('bindEnvironmentModal')}
async function boot(){try{const [status,spaces,envs]=await Promise.all([api('/v1/workspace/status'),api('/v1/workspaces'),api('/v1/environments').catch(()=>[])]);statusBadge.textContent=status.workspace_schema_ready?'ready':'not ready';inferenceBadge.textContent=status.chat_inference==='GATED_BENCHMARK_PENDING'?'AI gated':'AI';state.workspaces=spaces;state.allEnvironments=envs;renderWorkspaces();if(spaces.length)await selectWorkspace(spaces[0].workspace_id)}catch(e){err(e)}}
function renderWorkspaces(){workspaceList.innerHTML=state.workspaces.length?state.workspaces.map(w=>`<button class="item ${state.workspace?.workspace_id===w.workspace_id?'active':''}" onclick="selectWorkspace('${esc(w.workspace_id)}')"><strong>${esc(w.name)}</strong><small>${esc(w.description||w.workspace_id)}</small></button>`).join(''):'<div class="muted">Nenhum projeto ainda.</div>'}
async function createWorkspace(e){e.preventDefault();try{const w=await api('/v1/workspaces',{method:'POST',body:JSON.stringify({name:newWorkspaceName.value,description:newWorkspaceDescription.value||null})});closeModal('workspaceModal');e.target.reset();state.workspaces=await api('/v1/workspaces');renderWorkspaces();await selectWorkspace(w.workspace_id)}catch(x){err(x)}}
async function selectWorkspace(id){try{state.workspace=await api('/v1/workspaces/'+id);workspaceTitle.textContent=state.workspace.name;state.chats=await api(`/v1/workspaces/${id}/chats`);state.memories=await api(`/v1/workspaces/${id}/memories`);state.envBindings=await api(`/v1/workspaces/${id}/environments`);state.chat=null;state.messages=[];state.drafts=[];renderWorkspaces();renderChats();renderContext();composer.disabled=true;chatTitle.textContent=state.workspace.name;messages.innerHTML='<div class="empty"><h1>'+esc(state.workspace.name)+'</h1><p>Abra um chat ou crie um novo para começar.</p></div>';if(state.chats.length)await selectChat(state.chats[0].chat_id);side.classList.remove('open')}catch(e){err(e)}}
function renderChats(){chatList.innerHTML=state.chats.length?state.chats.map(c=>`<button class="item ${state.chat?.chat_id===c.chat_id?'active':''}" onclick="selectChat('${esc(c.chat_id)}')"><strong>${esc(c.title)}</strong><small>${c.active_environment_id?'Environment ativo':'Planejamento'}</small></button>`).join(''):'<div class="muted">Nenhum chat.</div>'}
async function createChat(e){e.preventDefault();try{const c=await api(`/v1/workspaces/${state.workspace.workspace_id}/chats`,{method:'POST',body:JSON.stringify({title:newChatTitle.value,active_environment_id:newChatEnvironment.value||null})});closeModal('chatModal');e.target.reset();state.chats=await api(`/v1/workspaces/${state.workspace.workspace_id}/chats`);renderChats();await selectChat(c.chat_id)}catch(x){err(x)}}
async function selectChat(id){try{state.chat=await api('/v1/chats/'+id);[state.messages,state.drafts]=await Promise.all([api(`/v1/chats/${id}/messages`),api(`/v1/chats/${id}/drafts`)]);chatTitle.textContent=state.chat.title;composer.disabled=false;renderChats();renderMessages();renderContext();fillEnvironmentSelects();side.classList.remove('open')}catch(e){err(e)}}
function renderMessages(){if(!state.messages.length){messages.innerHTML='<div class="empty"><h1>'+esc(state.chat.title)+'</h1><p>Use este chat para pensar e organizar. Executar continua sendo função de um Environment.</p></div>';return}messages.innerHTML=state.messages.map(m=>`<div class="message ${m.role==='OWNER'?'owner':''}"><div class="who">${m.role==='OWNER'?'Você':'Amodex'}</div><div class="bubble">${esc(m.content)}</div></div>`).join('');messages.scrollTop=messages.scrollHeight}
async function sendMessage(){const text=composer.value.trim();if(!state.chat||!text)return;try{await api(`/v1/chats/${state.chat.chat_id}/messages`,{method:'POST',body:JSON.stringify({role:'OWNER',content:text})});composer.value='';state.messages=await api(`/v1/chats/${state.chat.chat_id}/messages`);renderMessages()}catch(e){err(e)}}
composer.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage()}});
async function createMemory(e){e.preventDefault();try{await api(`/v1/workspaces/${state.workspace.workspace_id}/memories`,{method:'POST',body:JSON.stringify({content:memoryContent.value,source_ref:memorySource.value||null})});closeModal('memoryModal');e.target.reset();state.memories=await api(`/v1/workspaces/${state.workspace.workspace_id}/memories`);renderContext()}catch(x){err(x)}}
async function decideMemory(id,status){try{await api(`/v1/memories/${id}/decision`,{method:'POST',body:JSON.stringify({status})});state.memories=await api(`/v1/workspaces/${state.workspace.workspace_id}/memories`);renderContext()}catch(e){err(e)}}
async function createDraft(e){e.preventDefault();try{await api(`/v1/chats/${state.chat.chat_id}/drafts`,{method:'POST',body:JSON.stringify({title:draftTitle.value,objective:draftObjective.value,instructions:draftInstructions.value,validation:draftValidation.value||null,environment_id:draftEnvironment.value||null})});closeModal('draftModal');e.target.reset();state.drafts=await api(`/v1/chats/${state.chat.chat_id}/drafts`);renderContext()}catch(x){err(x)}}
async function setDraft(id,status){try{await api(`/v1/drafts/${id}/state`,{method:'POST',body:JSON.stringify({status})});state.drafts=await api(`/v1/chats/${state.chat.chat_id}/drafts`);renderContext()}catch(e){err(e)}}
async function bindEnvironment(e){e.preventDefault();try{await api(`/v1/workspaces/${state.workspace.workspace_id}/environments`,{method:'POST',body:JSON.stringify({environment_id:bindEnvironmentSelect.value,label:bindEnvironmentLabel.value||null})});closeModal('bindEnvironmentModal');e.target.reset();state.envBindings=await api(`/v1/workspaces/${state.workspace.workspace_id}/environments`);renderContext();fillEnvironmentSelects()}catch(x){err(x)}}
function envName(id){const e=state.allEnvironments.find(x=>x.environment_id===id);return e?.name||id}function fillEnvironmentSelects(){const bound=new Set(state.envBindings.map(x=>x.environment_id));const opts=state.envBindings.map(x=>`<option value="${esc(x.environment_id)}">${esc(x.label||envName(x.environment_id))}</option>`).join('');activeEnvironment.innerHTML='<option value="">Sem ambiente</option>'+opts;newChatEnvironment.innerHTML='<option value="">Nenhum</option>'+opts;draftEnvironment.innerHTML='<option value="">Selecionar depois</option>'+opts;if(state.chat?.active_environment_id)activeEnvironment.value=state.chat.active_environment_id;bindEnvironmentSelect.innerHTML=state.allEnvironments.filter(x=>!bound.has(x.environment_id)).map(x=>`<option value="${esc(x.environment_id)}">${esc(x.name)} · ${esc(x.engine||'generic')}</option>`).join('')||'<option value="" disabled>Nenhum Environment disponível</option>'}
function renderContext(){memoryList.innerHTML=state.memories.length?state.memories.map(m=>`<div class="context-card memory"><h4>${esc(m.status)}</h4><div>${esc(m.content)}</div>${m.status==='CANDIDATE'?`<div class="row" style="margin-top:8px"><button onclick="decideMemory('${esc(m.memory_id)}','APPROVED')">Aprovar</button><button onclick="decideMemory('${esc(m.memory_id)}','REJECTED')">Rejeitar</button></div>`:''}</div>`).join(''):'<div class="muted">Sem memórias.</div>';draftList.innerHTML=state.drafts.length?state.drafts.map(d=>`<div class="context-card draft"><h4>${esc(d.title)}</h4><div class="muted">${esc(d.status)} · ${d.environment_id?esc(envName(d.environment_id)):'sem Environment'}</div><p>${esc(d.objective)}</p>${d.status==='DRAFT'?`<div class="row"><button onclick="setDraft('${esc(d.draft_id)}','READY')">Marcar pronto</button><button onclick="setDraft('${esc(d.draft_id)}','CANCELLED')">Cancelar</button></div>`:''}</div>`).join(''):'<div class="muted">Sem drafts neste chat.</div>';boundEnvironmentList.innerHTML=state.envBindings.length?state.envBindings.map(b=>`<div class="context-card"><strong>${esc(b.label||envName(b.environment_id))}</strong><div class="muted">${esc(b.environment_id)}</div></div>`).join(''):'<div class="muted">Nenhum Environment vinculado.</div>';environmentList.innerHTML=state.envBindings.length?state.envBindings.map(b=>`<div class="item"><strong>${esc(b.label||envName(b.environment_id))}</strong><small>${esc(b.environment_id)}</small></div>`).join(''):'<div class="muted">Nenhum.</div>';fillEnvironmentSelects()}
boot();
</script>
</body></html>'''
